#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
using namespace std;

int main() {
    int n, k, mod;
    cin >> n >> k >> mod;

    auto power = [&](int a, int n) {
        int result = 1;
        while (n > 0) {
            if (n & 1) result = (long long)result * a % mod;
            a = (long long)a * a % mod;
            n >>= 1;
        }
        return result;
    };

    if (n % 2 == 1) {
        cout << power(k, n) << "\n";
    } else {
        vector<long long> fac(n + 1, 1), inv(n + 1, 1);
        for (int i = 1; i <= n; ++i) {
            fac[i] = fac[i - 1] * i % mod;
        }
        inv[n] = power(fac[n], mod - 2);
        for (int i = n - 1; i >= 0; --i) {
            inv[i] = inv[i + 1] * (i + 1) % mod;
        }

        vector<int> list;
        for (int i = 0; i < n; ++i) {
            if (n & (1 << i))
                list.push_back(i);
        }
        int cnt_list = list.size();

        vector<int> len(n + 1, 0);
        for (int i = 0; i <= n; ++i) {
            int j = i;
            while (j) {
                len[i]++;
                j = (j - 1) & j;
            }
        }

        vector<bool> vis(1 << n, false);
        for (int i = (1 << n) - 1; i >= 0; --i) {
            if (i == 0) break;
            vis[i] = true;
        }

        vector<vector<long long>> dp(n + 1, vector<long long>(1 << n, 0));
        dp[0][0] = 1;

        for (int mask = 0; mask <= (1 << n); ++mask) {
            for (int s = 0; s <= n; ++s) {
                if (dp[s][mask] == 0) continue;
                for (int sub = mask; sub; sub = (sub - 1) & mask) {
                    int l = min(k, len[mask ^ sub] + 1);
                    for (int s2 = 1; s2 <= l; ++s2) {
                        if (dp[s - 1][mask ^ sub]) {
                            dp[s][mask] = (dp[s][mask] + dp[s - 1][mask ^ sub] * inv[sub]) % mod;
                        }
                    }
                }
            }
        }

        long long answer = 0;
        int full_mask = (1 << n) - 1;
        for (int i = 0; i <= min(k, len[n]); ++i) {
            if (dp[i][full_mask]) {
                long long tmp = dp[i][full_mask] * fac[k] % mod;
                tmp = tmp * inv[k - i] % mod;
                tmp = tmp * inv[i] % mod;
                tmp = tmp * fac[n] % mod;
                answer = (answer + tmp) % mod;
            }
        }
        cout << (power(k, n) - answer + mod) % mod << "\n";
    }
    return 0;
}
